-- =====================================================================
-- SCRIPT SQL INSERT & UPDATE KEBUTUHAN DATABASE SURVEI RTKD BANYUWANGI
-- Untuk Server Production / cPanel phpMyAdmin
-- =====================================================================

SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
START TRANSACTION;
SET time_zone = '+07:00';

-- ---------------------------------------------------------------------
-- 1. PASTIKAN STRUKTUR TABEL & KOLOM BARU SUDAH SESUAI
-- ---------------------------------------------------------------------

-- Tabel survei_dinamis
CREATE TABLE IF NOT EXISTS `survei_dinamis` (
  `Id` int(11) NOT NULL AUTO_INCREMENT,
  `KodeSurvei` varchar(100) NOT NULL,
  `Judul` varchar(255) NOT NULL,
  `Deskripsi` text DEFAULT NULL,
  `Lembaga` varchar(255) DEFAULT NULL,
  `Jenis` varchar(100) NOT NULL DEFAULT 'IKM',
  `Tahun` varchar(10) NOT NULL DEFAULT '2026',
  `Status` varchar(20) NOT NULL DEFAULT 'Aktif',
  `TipeSurvei` varchar(50) NOT NULL DEFAULT 'standar',
  `InstrumenList` varchar(255) NOT NULL DEFAULT 'A',
  `DaerahSurvei` varchar(255) DEFAULT NULL,
  `KodeWilayah` varchar(50) DEFAULT NULL,
  `BannerImage` varchar(255) DEFAULT NULL,
  `BannerColor` varchar(30) DEFAULT '#043168',
  `EstimasiWaktu` varchar(50) DEFAULT '3 - 5 Menit',
  `CreatedBy` varchar(100) DEFAULT NULL,
  `CreatedAt` datetime DEFAULT NULL,
  `UpdatedAt` datetime DEFAULT NULL,
  PRIMARY KEY (`Id`),
  UNIQUE KEY `KodeSurvei` (`KodeSurvei`),
  KEY `idx_kode_survei` (`KodeSurvei`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4;

-- Tabel survei_pertanyaan
CREATE TABLE IF NOT EXISTS `survei_pertanyaan` (
  `Id` int(11) NOT NULL AUTO_INCREMENT,
  `SurveiId` int(11) NOT NULL,
  `Instrumen` varchar(10) DEFAULT 'A',
  `Pertanyaan` text NOT NULL,
  `Deskripsi` text DEFAULT NULL,
  `Section` varchar(150) DEFAULT NULL,
  `Tipe` varchar(30) NOT NULL DEFAULT 'radio',
  `OpsiPilihan` longtext DEFAULT NULL,
  `IsRequired` tinyint(1) NOT NULL DEFAULT 1,
  `Urutan` int(11) NOT NULL DEFAULT 1,
  `ScaleMin` int(11) NOT NULL DEFAULT 1,
  `ScaleMax` int(11) NOT NULL DEFAULT 5,
  `ScaleMinLabel` varchar(100) DEFAULT 'Sangat Tidak Baik',
  `ScaleMaxLabel` varchar(100) DEFAULT 'Sangat Baik',
  `CreatedAt` datetime DEFAULT NULL,
  `UpdatedAt` datetime DEFAULT NULL,
  PRIMARY KEY (`Id`),
  KEY `idx_survei_id` (`SurveiId`),
  KEY `idx_urutan` (`Urutan`)
) ENGINE=InnoDB AUTO_INCREMENT=167 DEFAULT CHARSET=utf8mb4;

-- Penyesuaian kolom baru pada survei_pertanyaan (jika tabel lama sudah ada)
ALTER TABLE `survei_pertanyaan` ADD COLUMN IF NOT EXISTS `Instrumen` VARCHAR(10) DEFAULT 'A' AFTER `SurveiId`;
ALTER TABLE `survei_pertanyaan` ADD COLUMN IF NOT EXISTS `Section` VARCHAR(150) NULL AFTER `Deskripsi`;

-- Tabel survei_responden
CREATE TABLE IF NOT EXISTS `survei_responden` (
  `Id` int(11) NOT NULL AUTO_INCREMENT,
  `SurveiId` int(11) NOT NULL,
  `Instrumen` varchar(10) DEFAULT 'A',
  `RespondenNama` varchar(150) DEFAULT 'Masyarakat',
  `RespondenNIK` varchar(25) DEFAULT NULL,
  `RespondenKontak` varchar(100) DEFAULT NULL,
  `RespondenGender` varchar(20) DEFAULT NULL,
  `RespondenUsia` varchar(20) DEFAULT NULL,
  `RespondenPendidikan` varchar(50) DEFAULT NULL,
  `RespondenPekerjaan` varchar(100) DEFAULT NULL,
  `Provinsi` varchar(100) DEFAULT NULL,
  `Kabupaten` varchar(100) DEFAULT NULL,
  `Kecamatan` varchar(100) DEFAULT NULL,
  `Desa` varchar(100) DEFAULT NULL,
  `AlamatDetail` text DEFAULT NULL,
  `Latitude` decimal(11,8) DEFAULT NULL,
  `Longitude` decimal(11,8) DEFAULT NULL,
  `LokasiAccuracy` decimal(8,2) DEFAULT NULL,
  `TotalSkor` decimal(10,2) NOT NULL DEFAULT 0.00,
  `RataRataSkor` decimal(10,2) NOT NULL DEFAULT 0.00,
  `MutuPelayanan` varchar(50) DEFAULT 'Baik',
  `IpAddress` varchar(45) DEFAULT NULL,
  `UserAgent` text DEFAULT NULL,
  `DevicePlatform` varchar(100) DEFAULT NULL,
  `CreatedBy` varchar(100) DEFAULT NULL,
  `CreatedAt` datetime DEFAULT NULL,
  PRIMARY KEY (`Id`),
  KEY `idx_resp_survei_id` (`SurveiId`),
  KEY `idx_resp_created_at` (`CreatedAt`)
) ENGINE=InnoDB AUTO_INCREMENT=143 DEFAULT CHARSET=utf8mb4;

-- Penyesuaian kolom baru pada survei_responden (jika tabel lama sudah ada)
ALTER TABLE `survei_responden` ADD COLUMN IF NOT EXISTS `Instrumen` VARCHAR(10) DEFAULT 'A' AFTER `SurveiId`;
ALTER TABLE `survei_responden` ADD COLUMN IF NOT EXISTS `LokasiAccuracy` DECIMAL(8,2) NULL AFTER `Longitude`;
ALTER TABLE `survei_responden` ADD COLUMN IF NOT EXISTS `DevicePlatform` VARCHAR(100) NULL AFTER `UserAgent`;

-- Tabel survei_jawaban
CREATE TABLE IF NOT EXISTS `survei_jawaban` (
  `Id` int(11) NOT NULL AUTO_INCREMENT,
  `RespondenId` int(11) NOT NULL,
  `PertanyaanId` int(11) NOT NULL,
  `JawabanTeks` text DEFAULT NULL,
  `NilaiAngka` decimal(10,2) NOT NULL DEFAULT 0.00,
  `CreatedAt` datetime DEFAULT NULL,
  PRIMARY KEY (`Id`),
  KEY `idx_jwb_responden_id` (`RespondenId`),
  KEY `idx_jwb_pertanyaan_id` (`PertanyaanId`)
) ENGINE=InnoDB AUTO_INCREMENT=4020 DEFAULT CHARSET=utf8mb4;

